#!/bin/bash
set -euo pipefail

ROOT="$(pwd)"
if [ ! -f "$ROOT/package.json" ] || [ ! -d "$ROOT/src" ]; then
  echo "ERROR: Run this script from the PaperRaj project root."
  exit 1
fi

BACKUP="$ROOT/.paperraj-logo-hydration-fix-backup-$(date +%Y%m%d-%H%M%S)"
mkdir -p "$BACKUP"

backup_file() {
  local f="$1"
  if [ -f "$ROOT/$f" ]; then
    mkdir -p "$BACKUP/$(dirname "$f")"
    cp "$ROOT/$f" "$BACKUP/$f"
  fi
}

for f in src/lib/useSession.ts src/components/Logo.tsx src/components/SiteHeader.tsx src/components/SiteFooter.tsx src/app/layout.tsx public/manifest.webmanifest; do
  backup_file "$f"
done

ICON_B64=''
mkdir -p "$ROOT/public"
printf '%s' "$ICON_B64" | base64 -d > "$ROOT/public/paperraj-icon.png"
echo "✓ public/paperraj-icon.png: compact PaperRaj tab/app icon installed"

python3 - "$ROOT" <<'PY'
from pathlib import Path
import re, sys

root = Path(sys.argv[1])

def patch(rel, fn, label):
    p = root / rel
    s = p.read_text(encoding="utf-8")
    out = fn(s)
    if out == s:
        print(f"✓ {rel}: {label} (already applied)")
    else:
        p.write_text(out, encoding="utf-8")
        print(f"✓ {rel}: {label}")

# Fix hydration: the initial render must be identical on server and browser.
def fix_session(s):
    s = s.replace(
        "const [user, setUser] = useState<SessionUser | null>(cached);\n  const [loading, setLoading] = useState(cached === null);",
        "const [user, setUser] = useState<SessionUser | null>(null);\n  const [loading, setLoading] = useState(true);"
    )
    old = """    listeners.add(listener);
    const fresh = Date.now() - cacheTimestamp < TTL;
    if (!fresh) {
      void refreshSession().then(() => setLoading(false));
    } else {
      setLoading(false);
    }"""
    new = """    listeners.add(listener);
    const fresh = Date.now() - cacheTimestamp < TTL;

    if (fresh) {
      setUser(cached);
      setLoading(false);
    } else {
      void refreshSession().then((next) => {
        setUser(next);
        setLoading(false);
      });
    }"""
    return s.replace(old, new)

patch("src/lib/useSession.ts", fix_session, "hydration-safe initial session state")

# Keep the supplied full logo as the single normal brand asset.
def fix_logo(s):
    return '''export function Logo({ size = 44, className = "" }: { size?: number; className?: string }) {
  const width = Math.round(size * 1.5);
  return (
    <img
      src="/paperraj-logo.png"
      width={width}
      height={size}
      alt="PaperRaj"
      className={`block h-auto w-auto object-contain ${className}`}
      draggable={false}
    />
  );
}

// Compatibility export for older consumers. The supplied logo already contains the wordmark.
export function LogoWordmark({ compact = false }: { compact?: boolean }) {
  return (
    <span className={`font-display font-semibold text-ink ${compact ? "text-xl" : "text-2xl"}`}>
      Paper<span className="text-wood-2">Raj</span>
    </span>
  );
}
'''

patch("src/components/Logo.tsx", fix_logo, "stable full-logo component")

def fix_header(s):
    s = s.replace("size={64}", "size={52}")
    s = s.replace('className="h-14 w-auto sm:h-16"', 'className="h-11 w-auto sm:h-14"')
    return s

patch("src/components/SiteHeader.tsx", fix_header, "right-sized header logo")

def fix_footer(s):
    pattern_mobile = r'''<div className="flex items-center gap-2\.5">\s*<Logo size=\{46\} />\s*<div>\s*<p className="font-display text-xl font-semibold text-ink">Paper<span className="text-wood-2">Raj</span></p>\s*<p className="text-\[0\.68rem\] text-ink-3">School question paper archive</p>\s*</div>\s*</div>'''
    s = re.sub(pattern_mobile,
               '<div className="flex items-center"><Logo size={64} className="h-12 w-auto" /></div>',
               s, count=1, flags=re.S)
    pattern_desktop = r'''<div className="flex items-center gap-3">\s*<Logo size=\{48\} />\s*<span className="font-display text-2xl font-semibold text-ink">Paper<span className="text-wood-2">Raj</span></span>\s*</div>'''
    s = re.sub(pattern_desktop,
               '<div className="flex items-center"><Logo size={72} className="h-14 w-auto" /></div>',
               s, count=1, flags=re.S)
    return s

patch("src/components/SiteFooter.tsx", fix_footer, "removed duplicate footer wordmark")

# Use the supplied emblem crop for browser tab and app icons.
def fix_layout(s):
    s = s.replace('/favicon.svg', '/paperraj-icon.png')
    s = s.replace('/icons/icon-192.png', '/paperraj-icon.png')
    s = s.replace('/icons/icon-512.png', '/paperraj-icon.png')
    s = s.replace('/icons/apple-touch-icon.png', '/paperraj-icon.png')
    return s

patch("src/app/layout.tsx", fix_layout, "browser tab and Apple icon")

def fix_manifest(s):
    s = s.replace('/icons/icon-192.png', '/paperraj-icon.png')
    s = s.replace('/icons/icon-512.png', '/paperraj-icon.png')
    return s

patch("public/manifest.webmanifest", fix_manifest, "PWA icon")

print("✓ Source patches complete")
PY

echo
 echo "Running checks..."
git diff --check

if npm run typecheck; then
  echo "✓ typecheck passed"
else
  echo
  echo "ERROR: typecheck failed."
  echo "Backup kept at: $BACKUP"
  exit 1
fi

if npm run build; then
  echo "✓ build passed"
else
  echo
  echo "ERROR: build failed."
  echo "Backup kept at: $BACKUP"
  exit 1
fi

echo
echo "=============================================="
echo "PAPERRAJ LOGO + HYDRATION FIX APPLIED"
echo "=============================================="
echo "Backup: $BACKUP"
echo "No commit or push was performed."
echo
echo "IMPORTANT: restart the dev server after this:"
echo "  npm run dev"
echo "Then hard-refresh the browser."
